/* ==========================================================================
   Mi RCR — pies.js
   Franja de aliados de cada área para la ÚLTIMA página del informe, recortada
   de las hojas oficiales (composición aprobada: logos ya alineados y con el
   margen del diseño). Se coloca al ancho del diseño y centrada. "ar"=ancho/alto.
   ========================================================================== */

window.PIES = {
  /* Pie ReCircula */
  recircula: { ar: 10.9462, src: "data:image/png;base64," },
  /* Pie Juntos Por La Vida */
  juntos_vida: { ar: 12.5538, src: "data:image/png;base64," },
  /* Pie Vidrio Mejor Planeta */
  vidrio: { ar: 9.8692, src: "data:image/png;base64," }
};

window.pieImg = function (areaKey, ancho) {
  var Q = window.PIES[areaKey];
  return Q ? '<img src="'+Q.src+'" alt="" style="width:'+ancho+'px;height:auto;display:block">' : '';
};
